// React view boundary; the fallback keeps the existing store/controller regression fixtures runnable.
function renderDepartmentHTML(element, markup) {
  if (window.ReactView) return window.ReactView.html(element, markup);
  element.innerHTML = markup; return markup;
}
function renderDepartmentText(element, value) {
  if (window.ReactView) return window.ReactView.text(element, value);
  element.textContent = value; return value;
}
/* 部门页面：账号内单位、人员与任务。字段和规则分别来自 data/store。 */
(() => {
  const store=window.DepartmentStore, config=window.DepartmentData,shared=window.TransferDemoData,app=document.getElementById('app');
  if(!store||!app)return;
  const homeEl=document.getElementById('dept'),work=document.getElementById('department-workspace');
  const overlay=document.createElement('div');overlay.id='departmentOverlay';overlay.className='dp-overlay';overlay.hidden=true;app.append(overlay);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const copy=v=>JSON.parse(JSON.stringify(v));
  const icon = name => '<i data-tabler=' + ({unit:'building', person:'user', collect:'clipboard-list', transfer:'arrows-exchange', pin:'map-pin', list:'list', home:'home', map:'map', phone:'phone', search:'search'}[name]) + '></i>';
  const btn=(label,action,extra='',primary=false)=>`<button type="button" class="dp-button${primary?' primary':''}" data-dp="${action}" ${extra}>${label}</button>`;
  const empty=msg=>`<div class="dp-empty">${icon('search')}<b>${esc(msg)}</b></div>`;
  const badge=status=>`<span class="dp-badge ${/异常|待补正/.test(status)?'red':/^(已|完成|开放)/.test(status)?'green':'orange'}">${esc(status)}</span>`;
  const mask=v=>String(v||'').replace(/(1\d{2})\d{4}(\d{4})/g,'$1****$2');
  const docMask=v=>v?String(v).slice(0,3)+'********'+String(v).slice(-4):'';
  const verification=v=>v?.status==='verified'?'已核查':'待核查';
  const state={page:{type:'home'},stack:[],collection:{status:'pending',mode:'list'},taskFilter:'all',taskPhase:'transfer',batch:false,selected:new Set(),mapMode:'task',expanded:new Set(),searchKind:'unit',searchText:'',searchFocus:false,query:'',unitExecutionFilter:'pending'};
  let picker=null,voice=null,speech=null,resolution=null;
  const toast=message=>{const el=document.getElementById('toast');renderDepartmentText(el, message);el.style.display='block';clearTimeout(window.__deptToast);window.__deptToast=setTimeout(()=>el.style.display='none',2400);};
  const show=id=>{app.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));window.scrollTo(0,0);};
  const currentForm=()=>work.querySelector('form');
  function capture(){if(state.page.form){state.page.form=readForm(state.page.form);if(['task','batch','execution'].includes(state.page.type))store.draft(draftKey(),state.page.form);}}
  const draftKey=()=>state.page.type+':'+(state.page.id||state.page.phase||'')+':'+(state.page.mode||'')+(state.page.batchOverride?':batch-override':'');
  function push(page){capture();state.stack.push({page:copy(state.page),scroll:window.scrollY||0});state.page=page;closeLayer();render();window.scrollTo(0,0);}
  function back(){closeLayer();capture();const prev=state.stack.pop();state.page=prev?.page||{type:'home'};render();window.scrollTo(0,prev?.scroll||0);}
  function home(){capture();closeLayer();state.stack=[];state.page={type:'home'};render();window.scrollTo(0,0);}
  function sheet(title,body){renderDepartmentHTML(overlay, `<div class="dp-backdrop" data-dp="close-layer"></div><section class="dp-sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="dp-sheet-title"><h2>${esc(title)}</h2><button data-dp="close-layer" aria-label="关闭"><i data-tabler=x></i></button></div>${body}</section>`);overlay.hidden=false;overlay.querySelector('input')?.focus();}
  function closeLayer(){overlay.hidden=true;renderDepartmentHTML(overlay, '');picker=null;voice=null;resolution=null;if(speech){speech.onresult=null;speech.stop();speech=null;}}
  function context(){renderDepartmentHTML(document.getElementById('departmentContext'), `<button class="brand-scope" data-dp="accounts"><i data-tabler=building-cog></i><span>${esc(store.account().name)}</span><b><i data-tabler=chevron-down></i></b></button><span class="brand-user">${esc(store.account().user)}</span>`);}
  function title(text,actions=''){return`<div class="dp-title"><button class="dp-back" data-dp="back" aria-label="返回上一页"><i data-tabler=chevron-left></i></button><h1>${esc(text)}</h1>${actions}</div>`;}
  function timeline(events){return`<section class="dp-card"><h2>办理经历</h2><div class="dp-timeline">${[...events].reverse().map(e=>`<article><span class="dp-time">${esc(e.at)} · ${esc(e.actorName||e.actor||'部门人员')}</span><b>${esc(e.type)}</b><p>${esc(e.detail)}</p>${e.photos?.length?photoView(e.photos):''}</article>`).join('')||'<p class="dp-muted">暂无办理记录</p>'}</div></section>`;}
  function homeRender(){const a=window.GridHomeData.getCurrentAction(),warn=window.GridHomeData.getActiveWarnings(),tasks=store.tasks(),units=store.units(),pending=tasks.filter(t=>t.status!=='已复核').length;
    const warnings=warn.map(w=>{const asset={'typhoon-orange':'warning-typhoon-orange','rainstorm-yellow':'warning-rainstorm-yellow'}[`${w.kind}-${w.level}`];return asset?`<img src="/assets/figma-home/${asset}.png" alt="${esc(w.label)}" width="58" height="50">`:`<span class="weather-warning ${esc(w.level)}" role="img" aria-label="${esc(w.label)}"><i data-tabler=${{typhoon:'storm',rainstorm:'cloud-rain',gale:'wind'}[w.kind]}></i><span>${esc(w.label)}</span></span>`;}).join('');
    renderDepartmentHTML(homeEl, `<div class="card home-action-card"><div class="home-action-summary"><div class="home-action-info"><h1 class="home-action-name ${a?'':'is-empty'}">${esc(a?.name||'当前暂无进行中的行动')}</h1><div class="home-action-heading">${a?'<span class="home-action-state">进行中</span>':''}</div></div><div class="home-weather" aria-label="当前有效气象预警">${warnings||'<span class="home-weather-empty">暂无有效预警</span>'}</div></div><div class="notice latest-notice"><span class="home-notice-art" aria-hidden="true"><img src="/assets/figma-home/notice-main.png" alt=""><img src="/assets/figma-home/notice-wave.png" alt=""><img src="/assets/figma-home/notice-wave-small.png" alt=""></span><b>最新通知</b><button data-dp="notices">${esc(window.WorkbenchNotices.summary())}</button>${window.WorkbenchNotices.unread()?`<i class="unread-dot">${window.WorkbenchNotices.unread()}</i>`:''}</div></div>
<div class="dp-section-heading"><h2>我的任务</h2><span>${pending}项人员待办</span></div><div class="dp-task-cards"><button class="dp-dashboard-task" data-dp="tasks"><span class="dp-dashboard-label"><img src="/assets/figma-home/transfer-icon.png" alt="">转移任务</span><strong>${tasks.length}<small>人次</small></strong><em>待转移 ${tasks.filter(t=>t.status==='待转移').length}<br>待复核 ${tasks.filter(t=>t.status==='待复核').length}</em></button><button class="dp-dashboard-task" data-dp="collection"><span class="dp-dashboard-label"><img src="/assets/figma-home/collection-icon.png" alt="">数据采集</span><strong>${units.length}<small>${store.account().type==='site'?'项目':'处单位'}</small></strong><em>待核查 ${units.filter(u=>u.verification.status!=='verified').length}</em></button></div>
<section class="dp-card dp-map-card"><div class="dp-section-heading"><h2>辖区动态</h2><div class="dp-map-switch" aria-label="地图内容">${['task','collection'].map(m=>`<button data-dp="home-map" data-value="${m}" class="${m===state.mapMode?'active':''}">${m==='task'?'任务':'采集'}</button>`).join('')}</div></div>${mapView(state.mapMode,'home')}</section>
<section class="dp-card"><div class="dp-section-heading"><h2>快捷搜索</h2></div><div class="dp-shortcuts"><button data-dp="shelters"><img src="/assets/figma-home/shelter-icon.png" alt="">安置点查询</button><button data-dp="contacts"><img src="/assets/figma-home/contact-icon.png" alt="">紧急联络</button></div></section>`);
    show('dept');
  }
  function mapView(mode,source){const groups=store.mapGroups(mode);return`<div class="dp-map" aria-label="${mode==='task'?'转移任务':'数据采集'}示意地图"><div class="dp-map-water"></div><div class="dp-road one"></div><div class="dp-road two"></div><div class="dp-road three"></div><small class="dp-map-caption">${mode==='task'?'任务点位':'采集点位'} · 示意位置</small>${groups.map(g=>`<button class="dp-marker ${g.color}${g.items.length===1&&['red','green'].includes(g.color)?' single-point':''}" style="left:${g.unit.mapPoint.x}%;top:${g.unit.mapPoint.y}%" data-dp="map-point" data-id="${esc(g.unit.id)}" data-mode="${mode}" data-source="${source}" aria-label="${esc(g.unit.name)}，${g.items.length}项"><span>${g.items.length===1&&g.color==='red'?'':g.items.length}</span></button>`).join('')}${groups.length?'':`<span class="dp-map-empty">当前暂无${mode==='task'?'三类待办':'采集'}点位</span>`}<div class="dp-legend">${(mode==='task'?[['red','异常'],['orange','待转移'],['yellow','待复核']]:[['red','待核查'],['green','已核查']]).map(([c,l])=>`<span><i class="${c}"></i>${l}</span>`).join('')}</div></div>`;}
  function unitRow(u,withStatus=false){return`<button class="dp-object-row" data-dp="unit" data-id="${esc(u.id)}"><span class="dp-row-icon">${icon('unit')}</span><span><b>${esc(u.name)}</b><small>${esc(u.address||'项目部地址待补充')}</small><em>${store.people(u.id).length}名已登记人员${u.unitType==='sea'?' · '+config.labels[u.objectType]:''}</em></span>${withStatus?badge(verification(u.verification)):''}<i><i data-tabler=chevron-right></i></i></button>`;}
  function personRow(p,withStatus=false){return`<button class="dp-object-row" data-dp="person" data-id="${esc(p.id)}" data-mid="${esc(p.membership.id)}"><span class="dp-row-icon person">${esc(p.name[0])}</span><span><b>${esc(p.name)}</b><small>${esc(store.unit(p.membership.unitId)?.name)} · ${esc(p.membership.identity)}</small><em>${esc(mask(p.phone)||'本人电话未填写')}</em></span>${withStatus?badge(verification(p.membership.verification)):''}<i><i data-tabler=chevron-right></i></i></button>`;}
  function collectionRender(){const rows=store.units().filter(u=>u.verification.status===state.collection.status);renderDepartmentHTML(work, title('数据采集',`<div class="dp-toolbar"><button data-dp="collection-mode" aria-label="切换${state.collection.mode==='list'?'地图':'列表'}模式">${icon(state.collection.mode==='list'?'map':'list')}</button><button data-dp="search" aria-label="搜索单位或人员">${icon('search')}</button></div>`)+`${state.collection.mode==='list'?`<div class="dp-tabs">${[['pending','待核查'],['verified','已核查']].map(([v,l])=>`<button class="${state.collection.status===v?'active':''}" data-dp="collection-status" data-value="${v}">${l}<small>${store.units().filter(u=>u.verification.status===v).length}</small></button>`).join('')}</div><p class="dp-count">${rows.length}处${esc(store.account().unitLabel)}</p><div class="dp-card dp-rows">${rows.map(u=>unitRow(u)).join('')||empty('当前暂无记录')}</div>`:mapView('collection','collection')}<div class="dp-bottom">${btn('<i data-tabler=plus></i> 新增'+store.account().unitLabel,'new-unit','',true)}</div>`);}
  function displayValue(f,r){let v=store.getPath(r,f.key);if(f.key==='departmentId')return store.account().fullName;if(f.key==='unitType'||f.key==='objectType')return config.labels[v]||'未选择';if(f.key==='streetId')return window.CollectionStore.scopes().find(x=>x.id===v)?.name||'未填写';if(f.key==='membership.unitId')return store.unit(v)?.name||'未关联';if(f.key.endsWith('verification.status'))return v==='verified'?'已核查':'待核查';if(f.type==='location')return store.hasGeo(v)?`${v.lng}, ${v.lat}`:'未填写';if(f.type==='tags')return(v||[]).map(id=>window.CollectionStore.tagCatalog('person',true).find(t=>t.id===id)?.name||window.CollectionStore.tagCatalog('person',true).find(t=>t.id===id)?.label||id).join('、')||'未选择';if(f.type==='tel')return mask(v)||'未填写';if(f.key==='documentNumber')return docMask(v)||'未填写';if(f.type==='choice'){const o=f.options.find(o=>(typeof o==='string'?o:o.value)===v);return(typeof o==='string'?o:o?.label)||v||'未填写';}return(v===0?'0':v)||'未填写';}
  function details(fields,r){let last='',html='';fields.filter(f=>store.visible(f,r)).forEach(f=>{if(f.group!==last){if(last)html+='</div></section>';html+=`<section class="dp-card"><h2>${esc(f.group)}</h2><div class="dp-detail-fields">`;last=f.group;}html+=`<div class="dp-detail-field" data-field-display="${esc(f.key)}"><span>${esc(f.label)}</span><b>${esc(displayValue(f,r))}</b></div>`;});return html+(last?'</div></section>':'');}
  function unitDetail(){
    const u=store.unit(state.page.id);if(!u)return unavailable();const tab=state.page.tab||'info';
    const summary=`<section class="dp-card dp-profile-summary"><div class="dp-object-hero"><span class="dp-hero-icon">${icon('unit')}</span><div><h2>${esc(u.name)}</h2><p>${esc(store.account().fullName)} · ${esc(config.labels[u.objectType||u.unitType])}</p></div>${badge(verification(u.verification))}</div><div class="dp-tabs"><button class="${tab==='info'?'active':''}" data-dp="unit-tab" data-value="info">信息</button><button class="${tab==='people'?'active':''}" data-dp="unit-tab" data-value="people">人员 <small>${store.people(u.id).length}</small></button></div>${tab==='info'?`<div class="dp-inline-actions">${btn('编辑资料','edit-unit')}${btn('地图定位','locate-unit')}${u.verification.status!=='verified'?btn('数据核查','verify-unit','',true):''}</div>`:''}</section>`;
    const content=tab==='info'?details(config.unitFields(store.account(),u),u):`<div class="dp-card dp-rows">${store.people(u.id).map(p=>personRow(p,true)).join('')||empty('暂无在册人员')}</div><div class="dp-bottom">${btn('<i data-tabler=plus></i> 新增人员','new-person','',true)}</div>`;
    renderDepartmentHTML(work,title(u.name)+summary+content);
  }
  function personDetail(){
    const p=store.person(state.page.id,state.page.mid);if(!p)return unavailable();
    renderDepartmentHTML(work,title('人员档案')+`<section class="dp-card dp-profile-summary"><div class="dp-object-hero"><span class="dp-hero-avatar">${esc(p.name[0])}</span><div><h2>${esc(p.name)}</h2><p>${esc(p.membership.identity)} · ${esc(store.unit(p.membership.unitId)?.name)}</p></div>${badge(verification(p.membership.verification))}</div><div class="dp-inline-actions">${btn('编辑资料','edit-person')}${btn('调整所属单位','move-person')}${p.membership.verification.status!=='verified'?btn('数据核查','verify-person','',true):''}</div></section>${details(config.personFields(store.account(),p),p)}<div class="dp-inline-actions">${btn('查看所属'+store.account().unitLabel+'及同单位人员','unit',`data-id="${esc(p.membership.unitId)}" data-tab="people"`)}</div>`);
  }
  function readonlyField(f,r){return`<div class="dp-readonly" data-field-readonly="${esc(f.key)}"><span>${esc(f.label)}</span><b>${esc(displayValue(f,r))}</b></div>`;}
  function formField(f,r){if(!store.visible(f,r))return'';if(f.readonly||(f.immutable&&state.page.editId))return readonlyField(f,r);const v=store.getPath(r,f.key),req=f.required?'<em class="required-mark">*</em>':'',heading=`<span>${esc(f.label)} ${req}</span>`,value=v??'';
    if(['choice','street','location','tags','shelter','relationship','careLevel'].includes(f.type)){let label='请选择';if(f.type==='location')label=store.hasGeo(v)?`${v.lng}, ${v.lat}`:'选择位置';else if(f.type==='shelter')label=shared.shelters.find(s=>s.id===v)?.name||'选择安置点';else if(f.type==='street')label=window.CollectionStore.scopes().find(s=>s.id===v)?.name||'请选择';else if(f.type==='tags')label=displayValue(f,r);else{const opts=f.options||shared.formOptions[f.type]||[];const o=opts.find(o=>(typeof o==='string'?o:o.value)===v);label=(typeof o==='string'?o:o?.label)||v||'请选择';}return`<label class="dp-form-field" data-field-wrap="${esc(f.key)}">${heading}<button type="button" class="dp-picker" aria-label="选择${esc(f.label)}" ${f.required?'aria-required="true"':''} data-dp="pick-field" data-key="${esc(f.key)}"><span>${esc(label)}</span><b><i data-tabler=chevron-down></i></b></button><span class="dp-field-error"></span></label>`;}
    const attrs=`data-dp-field="${esc(f.key)}" aria-label="${esc(f.label)}" ${f.required?'aria-required="true"':''}`;
    return`<label class="dp-form-field" data-field-wrap="${esc(f.key)}">${heading}${f.type==='textarea'?`<textarea ${attrs} rows="3" placeholder="${f.required?'请填写':'请输入'}">${esc(value)}</textarea>`:`<input ${attrs} value="${esc(value)}" ${f.type==='tel'?'inputmode="tel"':f.type==='integer'||f.type==='positive'?'inputmode="numeric"':f.type==='datetime'?'type="datetime-local"':''} placeholder="${f.required?'请填写':'请输入'}">`}<span class="dp-field-error"></span></label>`;
  }
  function formGroups(fields,r){let last='',html='',fold=false;fields.filter(f=>store.visible(f,r)).forEach(f=>{if(f.group!==last){if(last)html+=fold?'</div></details>':'</div></section>';fold=!['基本信息','负责人及联系','人员信息','单位关系','联系信息'].includes(f.group)&&f.group!=='维护记录';html+=fold?`<details class="dp-card dp-form-group"><summary>${esc(f.group)}</summary><div class="dp-form-fields">`:`<section class="dp-card"><h2>${esc(f.group)}</h2><div class="dp-form-fields">`;last=f.group;}html+=formField(f,r);});return html+(last?(fold?'</div></details>':'</div></section>'):'');}
  function editRender(){const p=state.page,kind=p.kind,record=p.form,fields=kind==='unit'?config.unitFields(store.account(),record):config.personFields(store.account(),record);renderDepartmentHTML(work, title(`${p.editId?'编辑':'新增'}${kind==='unit'?store.account().unitLabel:'人员'}`)+`<form novalidate><div class="dp-form-alert" role="alert" hidden></div>${formGroups(fields,record)}${kind==='unit'?`<div class="dp-inline-actions">${btn('备用联系同负责人','copy-contact')}</div>`:''}<div class="dp-bottom">${btn('保存资料','save-archive','',true)}</div></form>`);}
  function searchRender(){renderDepartmentHTML(work, title('搜索')+`<div class="dp-segment dp-search-target">${[['unit',store.account().unitLabel],['person','人员']].map(([v,l])=>`<button data-dp="search-kind" data-value="${v}" class="${state.searchKind===v?'active':''}">${esc(l)}</button>`).join('')}</div><form class="dp-search" id="departmentSearchForm">${icon('search')}<input id="departmentSearch" type="search" value="${esc(state.searchText)}" placeholder="${state.searchKind==='unit'?'搜索名称、地址、编号':'搜索姓名、电话、证件号码'}" aria-label="搜索关键词"><button type="submit">搜索</button></form><div id="departmentRecent"></div><div id="departmentSearchResults"></div>`);renderRecent();renderSearchRows();}
  function renderRecent(){const el=document.getElementById('departmentRecent');if(!el)return;el.hidden=!state.searchFocus||!!state.searchText.trim();renderDepartmentHTML(el, `<div class="dp-section-heading"><h2>最近搜索</h2></div><div class="dp-history">${store.recent(state.searchKind).map(q=>btn(esc(q),'recent',`data-value="${esc(q)}"`)).join('')}</div>`);}
  function renderSearchRows(){const el=document.getElementById('departmentSearchResults');if(!el)return;const rows=store.search(state.searchKind,state.searchText);renderDepartmentHTML(el, state.searchText.trim()?`<p class="dp-count">${rows.length}条搜索结果</p><div class="dp-card dp-rows">${rows.map(r=>state.searchKind==='unit'?unitRow(r,true):personRow(r,true)).join('')||empty('未找到匹配记录')}</div>`:'');}
  function taskRow(t){const p=store.taskPerson(t),ok=store.eligible(t,state.taskPhase),checked=state.selected.has(t.id);return`<div class="dp-person-task">${state.batch?`<button class="dp-check ${checked?'checked':''}" data-dp="select-task" data-id="${esc(t.id)}" ${ok?'':'disabled'} aria-label="${ok?'选择':'不可选择'}${esc(p?.name)}" aria-pressed="${checked}">${checked?'<i data-tabler=check></i>':''}</button>`:'<span class="dp-task-avatar">'+esc(p?.name[0]||'人')+'</span>'}<button class="dp-task-main" data-dp="task" data-id="${esc(t.id)}"><span><b>${esc(p?.name||'人员')}</b>${badge(t.status)}</span><small>${esc(mask(p?.phone)||'本人电话未填写')}${t.pendingCorrections.some(c=>c.status==='pending')?' · 有待补正':''}</small></button><span class="dp-chevron"><i data-tabler=chevron-right></i></span></div>`;}
  function tasksRender(){const groups=store.groups(state.taskFilter);renderDepartmentHTML(work, title('转移任务',btn(state.batch?'退出批量':'批量办理','batch-toggle'))+`<div class="dp-task-action"><span>${esc(shared.action.name)} · ${store.tasks().length}人次</span>${btn('单位执行','executions')}</div><div class="dp-tabs dp-status-tabs">${['all',...store.statuses].map(s=>`<button data-dp="task-status" data-value="${s}" class="${state.taskFilter===s?'active':''}">${s==='all'?'全部':s}<small>${store.tasks().filter(t=>s==='all'||t.status===s).length}</small></button>`).join('')}</div>${state.batch?`<div class="dp-batch-phase"><span>批量阶段</span><div class="dp-segment">${[['transfer','转移办理'],['review','安置复核']].map(([v,l])=>`<button data-dp="phase" data-value="${v}" class="${state.taskPhase===v?'active':''}">${l}</button>`).join('')}</div></div>`:''}${groups.map(g=>{const eligible=g.tasks.filter(t=>store.eligible(t,state.taskPhase)),count=eligible.filter(t=>state.selected.has(t.id)).length,progress=store.progress(g.execution.id),expanded=state.expanded.has(g.execution.id);return`<section class="dp-card dp-unit-group"><div class="dp-unit-heading">${state.batch?`<button class="dp-check ${count===eligible.length&&count?'checked':count?'partial':''}" data-dp="select-unit" data-id="${esc(g.execution.id)}" aria-label="选择${esc(g.unit.name)}" aria-pressed="${!!count}" ${eligible.length?'':'disabled'}>${count===eligible.length&&count?'<i data-tabler=check></i>':count?'<i data-tabler=minus></i>':''}</button>`:''}<button class="dp-group-label" data-dp="expand-unit" data-id="${esc(g.execution.id)}"><span class="dp-unit-symbol">${icon('unit')}</span><span><b>${esc(g.unit.name)}</b><small>${esc(store.instruction(g.execution.instructionId)?.name)}</small></span><strong>${g.tasks.length}<small>人</small></strong><i>${expanded?'<i data-tabler=chevron-up></i>':'<i data-tabler=chevron-down></i>'}</i></button></div><button class="dp-unit-progress" data-dp="execution" data-id="${esc(g.execution.id)}"><span>措施${progress.measuresDone?'已落实':'待落实'} · 人员已复核 ${progress.reviewed}/${progress.total}</span><b>${progress.complete?'已完成':'查看单位执行'} <i data-tabler=chevron-right></i></b></button>${expanded?`<div class="dp-unit-members">${g.tasks.map(taskRow).join('')}</div>`:''}</section>`;}).join('')||empty('当前暂无人员任务')}${state.batch?`<div class="dp-bottom"><span>已选 <b>${state.selected.size}</b> 人</span>${btn(state.taskPhase==='review'?'批量复核':'批量转移','batch-open',state.selected.size?'':'disabled',true)}</div>`:''}`);}
  function correctionsBlock(t){const rows=t.pendingCorrections.filter(c=>c.status==='pending');return rows.length?`<section class="dp-card dp-warning"><h2>待补正事项</h2>${rows.map(c=>`<div class="dp-correction"><p>${esc(c.note)}</p>${btn('确认补正已处理','resolve',`data-id="${esc(t.id)}" data-cid="${esc(c.id)}"`)}</div>`).join('')}</section>`:'';}
  function taskHero(t){const p=store.taskPerson(t),i=store.instruction(t.instructionId);return`<section class="dp-card dp-task-hero"><div class="dp-person-heading"><span class="dp-hero-avatar">${esc(p.name[0])}</span><div><h2>${esc(p.name)}</h2><p>${esc(t.unitName)} · ${esc(mask(p.phone)||'本人电话未填写')}</p></div>${badge(t.status)}</div><div class="dp-basis"><small>本次转移依据</small><b>${esc(i.name)}</b><p>${esc(i.requirement)}</p></div><div class="dp-inline-actions">${btn('人员档案及同单位人员','task-archive')}${store.tel(p.phone)?`<a class="dp-button" href="${esc(store.tel(p.phone))}">拨打电话</a>`:'<button class="dp-button" disabled>电话未填写</button>'}</div></section>`;}
  function taskForm(t){const saved=t.destination||t.plannedDestination;return{transferResult:t.transferResult||'',destination:copy(saved||{}),note:t.note||'',photos:copy(t.photos||[]),changeReason:''};}
  const destinationDescriptor=(key,label,type='text',extra=false)=>({key:'destination.'+key,label,group:'安置安排',type,extra,options:type==='relationship'||type==='careLevel'?shared.formOptions[type]:undefined});
  function placementHTML(form){const type=form.destination?.type;if(form.transferResult==='拒绝转移')return'';const resultField={key:'destination.type',label:'安置方式',type:'choice',options:Object.entries(shared.formOptions.placementLabel).map(([value,label])=>({value,label}))};let html=formField(resultField,form);if(!type)return html;const fields=(config.destinationFields[type]||[]).map(([k,l,t,x])=>destinationDescriptor(k,l,t,x));
    html+=fields.filter(f=>!f.extra).map(f=>formField(f,form)).join('');
    if(type==='center'){const s=shared.shelters.find(s=>s.id===form.destination.placeId);if(s)html+=`<div class="dp-center-info"><b>${esc(s.name)}</b><p>${esc(s.address)}</p><p>${esc(s.contact)} · ${esc(s.phone||'电话未配置')}</p><span class="dp-badge ${s.occupied>=s.capacity?'red':'green'}">${s.occupied}/${s.capacity}人${s.occupied>=s.capacity?' · 已满员':''}</span></div>`;}
    if(type==='unknown')html+='<p class="dp-muted">实际去向待明确，可继续跟进补充。</p>';
    html+=`<details class="dp-placement-extras"><summary>展示更多</summary>${fields.filter(f=>f.extra).map(f=>formField(f,form)).join('')}</details>`;return html;}
  function photoView(photos){return`<div class="dp-photos">${photos.map((p,n)=>`<div><img src="${esc(p.src)}" alt="${esc(p.label||'现场照片')}" loading="lazy"><small>${esc(p.label||'现场照片')} ${n+1}</small></div>`).join('')}</div>`;}
  function evidence(form){return`<div class="dp-evidence"><span>现场照片 </span>${photoView(form.photos||[])}<div class="dp-inline-actions"><label class="dp-button"><i data-tabler=camera></i>拍照/选图<input type="file" id="departmentPhoto" accept="image/*" capture="environment" hidden></label>${btn('使用示例照片','sample-photo')}${(form.photos||[]).length?btn('清空本次照片','clear-photos'):''}</div></div>`;}
  function transferFormHTML(form,mode='transfer'){const resultField={key:'transferResult',label:'办理结果',type:'choice',required:true,options:['转移途中','已落实安置','拒绝转移','人员不在现场','联系不上','其他异常']};return`<section class="dp-card"><h2>${mode==='transfer'?'现场办理':mode==='modify'?'修改安置安排':'补充安置信息'}</h2><div class="dp-form-fields">${mode==='transfer'?formField(resultField,form):''}<button type="button" class="dp-voice" data-dp="voice"><i data-tabler=microphone></i> 语音填写</button>${placementHTML(form)}${mode==='modify'||(mode==='transfer'&&(state.page.type==='batch'||!!(store.task(state.page.id)?.destination||store.task(state.page.id)?.plannedDestination)))?formField({key:'changeReason',label:'修改安置原因（已有安排变更时必填）',required:mode==='modify',type:'textarea'},form):''}${formField({key:'note',label:'办理说明',type:'textarea'},form)}${evidence(form)}</div></section>`;}
  function taskRender(){const t=store.task(state.page.id);if(!t)return unavailable();const currentMode=state.page.mode||'view';
    let content='';
    if(['transfer','supplement','modify'].includes(currentMode)){state.page.form ||= store.draft(draftKey())||taskForm(t);content=`<form novalidate><div class="dp-form-alert" role="alert" hidden></div>${transferFormHTML(state.page.form,currentMode)}<div class="dp-bottom">${btn('暂存','draft')}${btn(state.page.batchOverride?'保存个人安排':currentMode==='transfer'?'提交办理':'保存资料','save-task','',true)}</div></form>`;}
    else if(currentMode==='review'){state.page.form ||= {result:'通过',contact:'',note:'',photos:[]};content=`<form novalidate><div class="dp-form-alert" role="alert" hidden></div><section class="dp-card"><h2>安置复核</h2><p class="dp-help">确认即可记录一次复核，说明和照片选填。</p><div class="dp-form-fields">${formField({key:'result',label:'复核结果',type:'choice',options:shared.formOptions.result,required:true},state.page.form)}${formField({key:'contact',label:'接收人或联系方式'},state.page.form)}${formField({key:'note',label:'复核说明',type:'textarea'},state.page.form)}${evidence(state.page.form)}</div></section><div class="dp-bottom">${btn('确认本次复核','save-review','',true)}</div></form>`;}
    else {const d=store.normalizeDestination(t.destination||t.plannedDestination);content=`<section class="dp-card"><h2>安置安排</h2><div class="dp-current-placement">${d?`<b>${esc(shared.formOptions.placementLabel[d.type])}</b><p>${esc(d.placeName||d.contact||'详细去向待补充')}</p><p>${esc(d.address||'地址待补充')}</p><p>${esc(d.phone||'')}</p>`:'<p>尚未填写，可后补</p>'}</div><div class="dp-inline-actions">${store.eligible(t)?btn('继续转移办理','task-mode','data-value="transfer"'):''}${t.transferResult!=='拒绝转移'?btn('补充安置信息','task-mode','data-value="supplement"')+btn('修改安置安排','task-mode','data-value="modify"'):''}</div></section>${store.eligible(t,'review')?`<div class="dp-bottom">${btn(t.reviewRecords.length?'再次复核':'确认安置复核','task-mode','data-value="review"',true)}</div>`:''}`;}
    renderDepartmentHTML(work, title('逐人转移办理')+taskHero(t)+correctionsBlock(t)+content+`<div class="dp-review-count">已明确复核 ${t.reviewRecords.length} 次</div>`+timeline(t.events));
  }
  function executionRows(){const rows=store.executions().filter(e=>state.unitExecutionFilter==='all'||(store.progress(e.id).measuresDone?'done':'pending')===state.unitExecutionFilter);renderDepartmentHTML(work, title('单位执行')+`<div class="dp-tabs">${[['pending','待落实'],['done','已落实'],['all','全部']].map(([v,l])=>`<button data-dp="execution-filter" data-value="${v}" class="${state.unitExecutionFilter===v?'active':''}">${l}</button>`).join('')}</div>${rows.map(e=>{const p=store.progress(e.id);return`<button class="dp-card dp-execution-row" data-dp="execution" data-id="${esc(e.id)}"><div><h2>${esc(store.unit(e.unitId).name)}</h2>${badge(p.complete?'已完成':p.rosterPending?'清单待核实':'未完成')}</div><p>${esc(store.instruction(e.instructionId).name)}</p><span>单位措施 ${p.measuresDone?'已落实':'待落实'} · ${e.noTransferRequired?'明确无需转移人员':`人员复核 ${p.reviewed}/${p.total}`}${p.corrections.length?' · 待补正'+p.corrections.length:''}</span></button>`;}).join('')||empty('当前暂无单位执行记录')}`);}
  function executionRender(){const e=store.execution(state.page.id);if(!e)return unavailable();const u=store.unit(e.unitId),i=store.instruction(e.instructionId),p=store.progress(e.id);state.page.form ||= store.draft(draftKey())||{measures:Object.fromEntries(e.measures.map(m=>[m.key,m.result])),inspection:copy(e.inspection),note:e.note,photos:copy(e.photos),changeReason:''};const form=state.page.form;
    renderDepartmentHTML(work, title('单位执行')+`<section class="dp-card dp-task-hero"><div class="dp-person-heading"><span class="dp-hero-icon">${icon('unit')}</span><div><h2>${esc(u.name)}</h2><p>${esc(i.name)}</p></div>${badge(p.complete?'已完成':'未完成')}</div><div class="dp-basis"><p>${esc(i.requirement)}</p><small>截止 ${esc(i.deadline)}</small></div><div class="dp-progress-grid"><div><span>单位措施</span><b>${p.measuresDone?'已落实':'待落实'}</b></div><div><span>${e.noTransferRequired?'本次人员要求':'人员复核'}</span><b>${e.noTransferRequired?'无需转移人员':p.reviewed+'/'+p.total}</b></div></div>${p.rosterPending?'<p class="dp-alert">人员清单待核实，空名单不能视为已完成。</p>':''}${p.conflict?`<p class="dp-alert">${p.missing.length?'名册中 '+p.missing.map(x=>esc(x.name)).join('、')+' 尚无本指令任务，请反馈后台核对清单。':'指令人员清单存在冲突，暂不能完成。'}</p>${btn('反馈清单差异','roster-feedback')}`:''}${p.corrections.length?`<p class="dp-alert">有${p.corrections.length}项待补正，复核事实保留，处理后重新计算完成情况。</p>`:''}</section><div class="dp-tabs"><button class="${state.page.tab!=='people'?'active':''}" data-dp="execution-tab" data-value="info">信息</button><button class="${state.page.tab==='people'?'active':''}" data-dp="execution-tab" data-value="people">人员 ${p.total}</button></div>${state.page.tab==='people'?`<div class="dp-card">${e.personTaskIds.map(store.task).filter(Boolean).map(taskRow).join('')||empty(e.noTransferRequired?'本次明确无需转移人员':'人员清单待核实')}</div>`:`<form novalidate><div class="dp-form-alert" role="alert" hidden></div><section class="dp-card"><h2>措施办理</h2><div class="dp-form-fields">${e.measures.map(m=>formField({key:'measures.'+m.key,label:m.label,type:'choice',required:true,options:['已落实','未落实']},form)).join('')}<button type="button" class="dp-voice" data-dp="voice"><i data-tabler=microphone></i> 语音填写</button>${e.measures.some(m=>m.result==='已落实')?formField({key:'changeReason',label:'变更原因（已落实改未落实时必填）',type:'textarea'},form):''}${formField({key:'note',label:'执行说明',type:'textarea'},form)}${evidence(form)}</div></section><details class="dp-card dp-form-group"><summary>现场检查</summary><div class="dp-form-fields">${config.inspections[u.unitType].filter(f=>store.visible(f,u,e)).map(f=>formField({...f,when:null},form)).join('')}</div></details><div class="dp-bottom">${btn('暂存','draft')}${btn('提交单位措施','save-measures','',true)}</div></form>${timeline(e.events)}`}`);
  }
  function batchOpen(){const ids=[...state.selected].filter(id=>store.eligible(store.task(id),state.taskPhase));if(!ids.length)return toast('请先选择本阶段可办理人员');const form=state.taskPhase==='review'?{result:'通过',note:'',contact:'',photos:[]}:{transferResult:'',destination:{},note:'',photos:[]};push({type:'batch',phase:state.taskPhase,ids,form:store.draft('batch:'+state.taskPhase+':')||form,overrides:{},keep:[],preview:false});}
  function batchValues(tid){const p=state.page,t=store.task(tid);if(p.keep.includes(tid))return{...copy(p.form),destination:copy(t.destination||t.plannedDestination||{})};return p.overrides[tid]||p.form;}
  function batchRender(){const p=state.page;renderDepartmentHTML(work, title(p.phase==='review'?'批量安置复核':'批量转移办理')+`<p class="dp-help">已选${p.ids.length}人，共同填写后可逐人调整。</p><form novalidate><div class="dp-form-alert" role="alert" hidden></div>${p.phase==='review'?`<section class="dp-card"><h2>共同复核信息</h2><div class="dp-form-fields">${formField({key:'result',label:'复核结果',type:'choice',options:shared.formOptions.result,required:true},p.form)}${formField({key:'contact',label:'接收人或联系方式'},p.form)}${formField({key:'note',label:'复核说明',type:'textarea'},p.form)}${evidence(p.form)}</div></section>`:transferFormHTML(p.form)}<section class="dp-card"><h2>逐人安排</h2>${p.ids.map(tid=>{const t=store.task(tid),person=store.taskPerson(t);return`<div class="dp-batch-member"><span><b>${esc(person.name)}</b><small>${p.keep.includes(tid)?'保留原安排':p.overrides[tid]?'已单独调整':'使用共同填写'}</small></span>${p.phase==='transfer'?btn('单独调整','batch-override',`data-id="${esc(tid)}"`):''}${p.phase==='transfer'&&(t.destination||t.plannedDestination)?btn(p.keep.includes(tid)?'改用共同':'保留原安排','batch-keep',`data-id="${esc(tid)}"`):''}</div>`;}).join('')}</section><div class="dp-bottom"><span>${p.ids.length}人</span>${btn('预览并提交','batch-preview','',true)}</div></form>`);}
  function placementChanges(old,dest){const labels={type:'安置方式',placeId:'安置点',placeName:'地点名称',address:'地址',location:'位置',contact:'联系人',relationship:'关系',phone:'电话',detail:'房间/床位',careNeed:'照护需求',residentCount:'入住人数',careLevel:'护理等级',customType:'安置类型',transport:'交通方式',followupAt:'跟进时间'};return [...new Set([...Object.keys(old||{}),...Object.keys(dest||{})])].filter(k=>JSON.stringify(old?.[k])!==JSON.stringify(dest?.[k])).map(k=>labels[k]||k).join('、');}
  function batchPreview(){capture();const p=state.page;sheet('确认批量'+(p.phase==='review'?'复核':'办理'),`<p class="dp-help">将逐人保存以下内容，原有不同资料会被明确覆盖。失败项保留并可重试。</p><div class="dp-preview-list">${p.ids.map(tid=>{const t=store.task(tid),v=batchValues(tid),d=store.normalizeDestination(v.destination),old=t.destination||t.plannedDestination,will=old&&JSON.stringify(old)!==JSON.stringify(d);return`<article><b>${esc(store.taskPerson(t).name)}</b><p>${esc(p.phase==='review'?'确认复核：'+(v.result||'通过'):v.transferResult||'尚未选办理结果')} ${d?' · '+esc(shared.formOptions.placementLabel[d.type])+' · '+esc(d.placeName||d.address||'资料后补'):''}</p>${will?`<span class="dp-alert">将更新：${esc(placementChanges(old,d))}</span>`:''}<small>${esc(p.keep.includes(tid)?'保留原安排':p.overrides[tid]?'使用个人调整':'使用共同填写')} · ${esc(v.note||'说明未填')}</small></article>`;}).join('')}</div>${btn(p.phase==='review'?'确认逐人记录本次复核':'确认逐人提交','batch-submit','',true)}`);}
  function contactsRender(){const q=state.query.toLowerCase(),rows=store.contacts().filter(c=>[c.name,c.organization,c.position].some(v=>v.toLowerCase().includes(q)));renderDepartmentHTML(work, title('紧急联络')+`<div class="dp-search">${icon('search')}<input id="departmentContactSearch" value="${esc(state.query)}" placeholder="搜索姓名、单位、职务" aria-label="搜索联络人"></div><p class="dp-count">本部门及公共应急联络 · ${rows.length}位</p><div class="dp-card dp-rows">${rows.map(c=>`<button class="dp-object-row" data-dp="contact" data-id="${esc(c.id)}"><span class="dp-row-icon person">${esc(c.name[0])}</span><span><b>${esc(c.name)}</b><small>${esc(c.organization)} · ${esc(c.position)}</small></span><i><i data-tabler=chevron-right></i></i></button>`).join('')||empty('未找到联络人')}</div>`);}
  function unavailable(){renderDepartmentHTML(work, title('无法打开')+empty('该对象不在当前账号授权范围'));}
  function render(){const savedScroll=window.scrollY||0;context();if(state.page.type==='home'){homeRender();return;}switch(state.page.type){case'collection':collectionRender();break;case'unit':unitDetail();break;case'person':personDetail();break;case'edit':editRender();break;case'search':searchRender();break;case'tasks':tasksRender();break;case'task':taskRender();break;case'executions':executionRows();break;case'execution':executionRender();break;case'batch':batchRender();break;case'contacts':contactsRender();break;default:unavailable();}show('department-workspace');window.scrollTo(0,savedScroll);}
  function readForm(base){const out=copy(base||{});currentForm()?.querySelectorAll('[data-dp-field]').forEach(el=>store.setPath(out,el.dataset.dpField,el.value));return out;}
  function formFields(){const p=state.page,r=p.form;if(p.type==='edit')return p.kind==='unit'?config.unitFields(store.account(),r):config.personFields(store.account(),r);if(p.type==='execution'){const e=store.execution(p.id),u=store.unit(e.unitId);return[...e.measures.map(m=>({key:'measures.'+m.key,label:m.label,type:'choice',options:['已落实','未落实']})),...config.inspections[u.unitType].filter(f=>store.visible(f,u,e)).map(f=>({...f,when:null}))];}return[{key:'transferResult',label:'办理结果',type:'choice',options:['转移途中','已落实安置','拒绝转移','人员不在现场','联系不上','其他异常']},{key:'destination.type',label:'安置方式',type:'choice',options:Object.entries(shared.formOptions.placementLabel).map(([value,label])=>({value,label}))},{key:'result',label:'复核结果',type:'choice',options:shared.formOptions.result},...(config.destinationFields[r?.destination?.type]||[]).map(([k,l,t,x])=>destinationDescriptor(k,l,t,x))];}
  function validation(out){if(out.ok)return false;const box=work.querySelector('.dp-form-alert');if(box){box.hidden=false;renderDepartmentText(box, out.error);}work.querySelectorAll('.dp-field-error').forEach(el=>renderDepartmentText(el, ''));work.querySelectorAll('[aria-invalid]').forEach(el=>{el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby');});(out.missing||[]).forEach(m=>{const field=work.querySelector(`[data-field-wrap="${m.key}"]`);if(field){const error=field.querySelector('.dp-field-error');error.id='department-error-'+m.key.replace(/[^a-z0-9_-]/gi,'-');renderDepartmentText(error,m.label);const control=field.querySelector('input,textarea,button');control?.setAttribute('aria-invalid','true');control?.setAttribute('aria-describedby',error.id);field.closest('details')?.setAttribute('open','');}});(work.querySelector('.dp-field-error:not(:empty)')||box)?.scrollIntoView?.({block:'center'});toast(out.error);return true;}
  function pickerOpen(key){capture();const f=formFields().find(f=>f.key===key);if(!f)return;if(f.type==='location')return locationSheet(key);if(f.type==='tags')return tagSheet(key);let opts=f.options||shared.formOptions[f.type]||[];if(f.type==='street')opts=window.CollectionStore.scopes().filter(s=>s.type==='street').map(s=>({value:s.id,label:s.name}));if(f.type==='shelter')opts=shared.shelters.map(s=>({value:s.id,label:s.name,detail:`${s.occupied}/${s.capacity}人 · ${s.status}${s.occupied>=s.capacity?' · 已满员':''}`}));picker={key,options:[{value:'',label:'暂不填写'},...opts.map(o=>typeof o==='string'?{value:o,label:o}:o)],label:f.label};sheet(f.label,`<input class="dp-layer-search" id="departmentPickerSearch" placeholder="搜索选项" aria-label="搜索选项"><div id="departmentPickerRows"></div>`);renderPicker('');}
  function renderPicker(q){const el=document.getElementById('departmentPickerRows');if(!el||!picker)return;renderDepartmentHTML(el, picker.options.map((o,i)=>({...o,index:i})).filter(o=>(o.label+' '+(o.detail||'')).includes(q)).map(o=>`<button class="dp-option ${store.getPath(state.page.form,picker.key)===o.value?'selected':''}" data-dp="pick-option" data-index="${o.index}"><span>${esc(o.label)}${o.detail?`<small>${esc(o.detail)}</small>`:''}</span><b>${store.getPath(state.page.form,picker.key)===o.value?'<i data-tabler=check></i>':'<i data-tabler=chevron-right></i>'}</b></button>`).join('')||empty('没有匹配选项'));}
  function choose(key,value){capture();const form=state.page.form,old=store.getPath(form,key);if(key==='destination.type'&&old!==value)form.destination=value?{type:value}:{};else if(key==='destination.placeId'){form.destination={...form.destination,type:'center',placeId:value};}else store.setPath(form,key,value);if(key==='transferResult'&&value==='拒绝转移')form.destination={};if(key==='documentType'&&!value&&form.documentNumber){sheet('清除证件信息',`<p class="dp-help">清除证件类型需同时清除已填写的号码。</p>${btn('同时清空类型与号码','clear-document','',true)}${btn('保留原信息','restore-document',`data-value="${esc(old)}"`)}`);return;}closeLayer();render();}
  function locationSheet(key){const points=shared.addressExamples||[];picker={key};sheet('选择位置',`<p class="dp-help">选择已有示例地址会带出登记坐标。示意图点位不能作为真实导航坐标。</p><div class="dp-map"><div class="dp-road one"></div><div class="dp-road two"></div><span class="dp-map-caption">示例地址位置</span>${points.map((p,i)=>`<button class="dp-marker orange" style="left:${20+i*20}%;top:${30+(i%2)*25}%" data-dp="location-example" data-index="${i}" aria-label="${esc(p.name)}"><span>${i+1}</span></button>`).join('')}</div>${points.map((p,i)=>`<button class="dp-option" data-dp="location-example" data-index="${i}"><span>${esc(p.name)}<small>${esc(p.address)}</small></span><i data-tabler=chevron-right></i></button>`).join('')}<div class="dp-coordinate"><label>经度<input id="dpLng" inputmode="decimal" value="${esc(store.getPath(state.page.form,key)?.lng||'')}"></label><label>纬度<input id="dpLat" inputmode="decimal" value="${esc(store.getPath(state.page.form,key)?.lat||'')}"></label></div>${btn('确认经纬度','location-save','',true)}${btn('清空位置','location-clear')}`);}
  function tagSheet(key){picker={key,tags:copy(store.getPath(state.page.form,key)||[])};const tags=window.CollectionStore.tagCatalog('person',true);sheet('人员标签',`<div class="dp-tags">${tags.map(t=>`<button data-dp="tag" data-id="${esc(t.id)}" class="${picker.tags.includes(t.id)?'selected':''}" ${t.enabled===false?'disabled':''}>${esc(t.name||t.label||t.id)}</button>`).join('')}</div>${btn('确认选择','tags-save','',true)}`);}
  function mapPoint(uid,mode){const g=store.mapGroups(mode).find(g=>g.unit.id===uid);if(!g)return;sheet(g.unit.name,`<p class="dp-help">${uid.startsWith('housing')?'项目部示意位置':g.unit.objectType==='vessel'?'登记位置（非实时）':'单位示意位置'}</p>${g.items.map(item=>`<button class="dp-option" data-dp="${item.type==='unit'?'unit':'task'}" data-id="${esc(item.id)}"><span>${esc(item.label)}</span>${badge(item.status)}<b><i data-tabler=chevron-right></i></b></button>`).join('')}`);}
  function archiveOpen(kind,record,editId){push({type:'edit',kind,editId:editId||null,mid:record.membership?.id,form:copy(record)});}
  function taskOpen(tid){const t=store.task(tid);if(!t)return toast('任务不在当前部门范围');push({type:'task',id:tid,mode:store.eligible(t)?'transfer':'view'});}
  function voiceOpen(){capture();voice={preview:null};sheet('语音填写',`<p class="dp-help">可录入安置方式、去向、联系信息、说明等；不会代选办理结果或提交。</p><textarea id="departmentVoiceText" rows="4" placeholder="输入或语音转写一段话" aria-label="语音转写原文"></textarea><div class="dp-inline-actions">${btn('开始语音转写','voice-record')}${btn('填入示例','voice-example')}</div>${btn('识别并预览','voice-parse','',true)}<div id="departmentVoicePreview"></div>`);}
  function parseVoice(){const text=document.getElementById('departmentVoiceText').value;voice.preview={};const form=state.page.form;
    if(state.page.type==='execution'){
      let rest=text;formFields().filter(f=>f.key.startsWith('inspection.')).forEach(f=>{const pos=rest.indexOf(f.label);if(pos<0)return;const raw=rest.slice(pos+f.label.length).replace(/^[：:\s]*/,'').split(/[，,。；;\n]/)[0];const val=f.type==='choice'?f.options.find(o=>raw===o):f.type==='integer'?raw.match(/^\d+$/)?.[0]:raw;if(val){voice.preview[f.key]=val;rest=rest.replace(f.label+text.slice(text.indexOf(f.label)+f.label.length).match(/^[：:\s]*/)[0]+raw,'');}});const note=rest.replace(/^[，,。；;\s]+|[，,。；;\s]+$/g,'');if(note)voice.preview.note=note;
    }else{const parsed=window.TransferStore.parseVoice(text);const type=parsed.type||form.destination?.type;Object.entries(parsed).forEach(([k,v])=>{if(k==='note')voice.preview.note=v;else if(k==='type')voice.preview['destination.type']=v;else if((config.destinationFields[type]||[]).some(f=>f[0]===k))voice.preview['destination.'+k]=v;else voice.preview.note=[voice.preview.note,`${k}：${v}`].filter(Boolean).join('；');});}
    renderDepartmentHTML(document.getElementById('departmentVoicePreview'), `<h3>填充预览</h3><p class="dp-help">${esc(text)}</p>${Object.entries(voice.preview).map(([k,v])=>{const label=k==='note'?'办理说明':k==='destination.type'?'安置方式':formFields().find(f=>f.key===k)?.label||config.destinationFields[voice.preview['destination.type']||form.destination?.type]?.find(f=>'destination.'+f[0]===k)?.[1]||k;return`<div class="dp-readonly"><span>${esc(label)}${store.getPath(form,k)?'（将更新已有值）':''}</span><b>${esc(k==='destination.type'?shared.formOptions.placementLabel[v]:v)}</b></div>`;}).join('')}${btn('确认填入','voice-apply','',true)}`);}
  function resolutionSheet(tid,cid){resolution={tid,cid,note:'',photos:[]};renderResolution();}
  function captureEvidence(){if(resolution)resolution.note=document.getElementById('departmentResolutionNote')?.value??resolution.note;else capture();}
  function renderResolution(){sheet('确认补正已处理',`<p class="dp-help">确认已处理当前事项，保留原复核事实。</p><label class="dp-form-field"><span>处理说明 </span><textarea id="departmentResolutionNote" rows="3">${esc(resolution.note)}</textarea></label>${evidence(resolution)}${btn('确认已处理','resolve-confirm',`data-id="${esc(resolution.tid)}" data-cid="${esc(resolution.cid)}"`,true)}`);}
  function samplePhoto(){captureEvidence();const svg='<svg xmlns="http://www.w3.org/2000/svg" width="480" height="320"><rect width="480" height="320" fill="#f0f0f3"/><path d="M30 270V130L240 45l210 85v140Z" fill="#cdced6"/><rect x="195" y="160" width="90" height="110" fill="#0090ff"/><text x="240" y="115" font-family="sans-serif" font-size="25" text-anchor="middle" fill="#1c2024">现场凭证 · 示例</text><text x="240" y="302" font-family="sans-serif" font-size="15" text-anchor="middle" fill="#1c2024">示例图片，不代表真实拍摄</text></svg>';(resolution||state.page.form).photos.push({id:'photo-'+Date.now(),src:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg),label:'现场凭证示例'});if(resolution)renderResolution();else render();}
  app.addEventListener('click',e=>{
    if(document.body.dataset.role!=='dept')return;
    const notice=e.target.closest('[data-message-id],[data-message-filter],[data-workbench]');
    if(notice&&['notice-list','notice-detail'].includes(app.querySelector('.view.active')?.id)){e.preventDefault();e.stopImmediatePropagation();if(notice.dataset.messageId)window.WorkbenchNotices.openMessage(Number(notice.dataset.messageId));else if(notice.dataset.messageFilter)window.WorkbenchNotices.setFilter(notice.dataset.messageFilter);else if(notice.dataset.workbench==='home')home();else window.WorkbenchNotices.open();return;}
    const b=e.target.closest('[data-dp]');if(!b||b.disabled)return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.dp,id=b.dataset.id,v=b.dataset.value;
    if(a==='back')return back();if(a==='close-layer')return closeLayer();if(a==='accounts')return sheet('切换部门账号',store.data.accounts.map(d=>`<button class="dp-option ${d.accountId===store.account().accountId?'selected':''}" data-dp="account" data-value="${d.accountId}"><span>${esc(d.name)}<small>${esc(d.user)}</small></span><b>${d.accountId===store.account().accountId?'<i data-tabler=check></i>':'<i data-tabler=chevron-right></i>'}</b></button>`).join(''));
    if(a==='account'){capture();if(store.switchAccount(v)){state.page={type:'home'};state.selected.clear();state.batch=false;state.expanded.clear();state.searchText='';state.query='';state.taskFilter='all';state.collection={status:'pending',mode:'list'};home();}return;}
    if(a==='home-map'){state.mapMode=v;return homeRender();}if(a==='map-point')return mapPoint(id,b.dataset.mode);
    if(a==='notices')return window.WorkbenchNotices.open();if(a==='shelters'){window.GridShelters.open({scopeId:'dt',home:'dept'});return;}
    if(a==='contacts'){state.query='';return push({type:'contacts'});}if(a==='contact'){const c=store.contacts().find(c=>c.id===id);if(c)sheet('联络人详情',`<div class="dp-contact-detail"><h2>${esc(c.name)}</h2><p>${esc(c.organization)} · ${esc(c.position)}</p><b>${esc(c.phone||'电话未配置')}</b></div>${store.tel(c.phone)?`<a class="dp-button primary" href="${esc(store.tel(c.phone))}">${icon('phone')}拨打电话</a>`:'<button class="dp-button" disabled>电话未配置</button>'}`);return;}
    if(a==='collection')return push({type:'collection'});if(a==='collection-mode'){state.collection.mode=state.collection.mode==='list'?'map':'list';return render();}if(a==='collection-status'){state.collection.status=v;return render();}
    if(a==='search'){state.searchText='';state.searchFocus=false;return push({type:'search'});}if(a==='search-kind'){state.searchKind=v;state.searchText='';state.searchFocus=false;return render();}if(a==='recent'){state.searchText=v;state.searchFocus=false;store.remember(state.searchKind,v);return render();}
    if(a==='unit')return push({type:'unit',id,tab:b.dataset.tab||'info'});if(a==='person')return push({type:'person',id,mid:b.dataset.mid});if(a==='unit-tab'){state.page.tab=v;return render();}
    if(a==='new-unit')return archiveOpen('unit',{departmentId:store.account().id,unitType:store.account().type,verification:{status:'pending'},location:null});
    if(a==='edit-unit'){const u=store.unit(state.page.id);return archiveOpen('unit',u,u.id);}
    if(a==='new-person')return archiveOpen('person',{membership:{unitId:state.page.id,identity:'',status:'在册',verification:{status:'pending'}},emergencyContact:{},tagIds:[]});
    if(a==='edit-person'){const p=store.person(state.page.id,state.page.mid);return archiveOpen('person',p,p.id);}
    if(a==='copy-contact'){capture();state.page.form.contactName=state.page.form.principalName;state.page.form.contactPhone=state.page.form.principalPhone;return render();}
    if(a==='save-archive'){capture();const p=state.page,out=p.kind==='unit'?store.saveUnit(p.form,p.editId):store.savePerson(p.form,p.editId,p.mid);if(validation(out))return;back();if(p.kind==='unit'&&state.page.type==='collection')push({type:'unit',id:out.item.id,tab:'info'});else if(p.kind==='person'&&state.page.type==='person')state.page.mid=out.item.membership.id;render();toast('资料已保存');return;}
    if(a==='verify-unit'||a==='verify-person'){const p=state.page;sheet('数据核查',`<p class="dp-help">确认当前${a==='verify-unit'?store.account().unitLabel:'人员'}基础资料已核查。此操作不改变单位措施或人员转移状态。</p>${btn('确认核查','verify-confirm',`data-kind="${a==='verify-unit'?'unit':'person'}" data-id="${esc(p.id)}" data-mid="${esc(p.mid||'')}"`,true)}`);return;}
    if(a==='verify-confirm'){const out=store.verify(b.dataset.kind,id,b.dataset.mid);if(validation(out))return;closeLayer();render();return toast('已记录数据核查');}
    if(a==='move-person'){sheet('调整所属单位',`<input class="dp-layer-search" id="departmentMoveSearch" placeholder="搜索已有单位"><div id="departmentMoveRows">${store.units().map(u=>`<button class="dp-option" data-dp="move-confirm" data-id="${esc(u.id)}"><span>${esc(u.name)}</span><i data-tabler=chevron-right></i></button>`).join('')}</div>`);return;}
    if(a==='move-confirm'){const out=store.move(state.page.id,state.page.mid,id);if(validation(out))return;state.page.mid=out.item.membership.id;closeLayer();render();return toast('单位关联已调整，既有任务归属保持原记录');}
    if(a==='locate-unit'){const u=store.unit(state.page.id);sheet(u.name,`${mapView('collection','locate')}<p class="dp-help">${esc(u.address)}${u.unitType==='site'?'；仅表示项目部位置':''}${u.objectType==='vessel'?'；登记位置（非实时）':''}</p>`);return;}
    if(a==='pick-field')return pickerOpen(b.dataset.key);if(a==='pick-option'){const p=picker,o=p?.options[Number(b.dataset.index)];if(o)return choose(p.key,o.value);return;}
    if(a==='clear-document'){state.page.form.documentType='';state.page.form.documentNumber='';closeLayer();return render();}if(a==='restore-document'){state.page.form.documentType=v;closeLayer();return render();}
    if(a==='location-example'){const p=shared.addressExamples[Number(b.dataset.index)],key=picker.key;store.setPath(state.page.form,key,{lng:p.lng,lat:p.lat});if(key==='destination.location')state.page.form.destination.address=p.address;closeLayer();return render();}
    if(a==='location-save'){const lng=document.getElementById('dpLng').value,lat=document.getElementById('dpLat').value,val={lng:Number(lng),lat:Number(lat)};if(!lng||!lat||!store.hasGeo(val))return toast('请填写有效经纬度');store.setPath(state.page.form,picker.key,val);closeLayer();return render();}
    if(a==='location-clear'){store.setPath(state.page.form,picker.key,null);closeLayer();return render();}
    if(a==='tag'){const n=picker.tags.indexOf(id);if(n<0)picker.tags.push(id);else picker.tags.splice(n,1);b.classList.toggle('selected',n<0);return;}if(a==='tags-save'){store.setPath(state.page.form,picker.key,picker.tags);closeLayer();return render();}
    if(a==='tasks')return push({type:'tasks'});if(a==='task-status'){state.taskFilter=v;state.selected.clear();return render();}if(a==='expand-unit'){state.expanded.has(id)?state.expanded.delete(id):state.expanded.add(id);return render();}
    if(a==='task')return taskOpen(id);if(a==='task-archive'){const t=store.task(state.page.id);return push({type:'person',id:t.personId,mid:t.membershipId});}
    if(a==='task-mode'){capture();state.page.mode=v;state.page.form=store.draft(draftKey())||(v==='review'?{result:'通过',contact:'',note:'',photos:[]}:taskForm(store.task(state.page.id)));return render();}
    if(a==='save-task'){capture();if(state.page.batchOverride){const p=state.page,prev=state.stack.at(-1);if(prev?.page.type==='batch'){prev.page.overrides[p.id]=copy(p.form);prev.page.keep=prev.page.keep.filter(x=>x!==p.id);back();return toast('已保存个人安排到本次批量草稿，尚未提交');}}const out=store.saveTask(state.page.id,state.page.form,state.page.mode);if(validation(out))return;store.draft(draftKey(),null);state.page.form=null;state.page.mode='view';render();return toast(out.unchanged?'资料未变化':'已保存并记录办理经历');}
    if(a==='save-review'){capture();const out=store.review(state.page.id,state.page.form);if(validation(out))return;store.draft(draftKey(),null);state.page.form=null;state.page.mode='view';render();return toast('已记录本次复核');}
    if(a==='draft'){capture();return toast('草稿已暂存，可返回后继续');}
    if(a==='resolve')return resolutionSheet(id,b.dataset.cid);
    if(a==='resolve-confirm'){captureEvidence();const out=store.resolve(id,b.dataset.cid,{note:resolution?.note||'',photos:resolution?.photos||[]});if(validation(out))return;closeLayer();render();return toast('补正已处理，已重新计算单位进度');}
    if(a==='executions')return push({type:'executions'});if(a==='execution-filter'){state.unitExecutionFilter=v;return render();}if(a==='execution')return push({type:'execution',id,tab:'info'});if(a==='execution-tab'){capture();state.page.tab=v;return render();}
    if(a==='save-measures'){capture();const out=store.saveMeasures(state.page.id,state.page.form);if(validation(out))return;store.draft(draftKey(),null);render();return toast('单位措施已记录');}
    if(a==='roster-feedback'){const e=store.execution(state.page.id);e.events.push({id:'feedback-'+Date.now(),at:new Date().toLocaleString('sv-SE'),actorName:store.account().user,type:'反馈清单差异',detail:'已记录本单位名册与指令任务差异，请后台核对。移动端未自动增删任务。'});render();return toast('清单差异已记录到单位办理经历');}
    if(a==='batch-toggle'){state.batch=!state.batch;state.selected.clear();return render();}if(a==='phase'){state.taskPhase=v;state.selected.clear();return render();}
    if(a==='select-task'){const t=store.task(id);if(!store.eligible(t,state.taskPhase))return;state.selected.has(id)?state.selected.delete(id):state.selected.add(id);return render();}
    if(a==='select-unit'){const ids=store.groups(state.taskFilter).find(g=>g.execution.id===id)?.tasks.filter(t=>store.eligible(t,state.taskPhase)).map(t=>t.id)||[],all=ids.every(id=>state.selected.has(id));ids.forEach(id=>all?state.selected.delete(id):state.selected.add(id));return render();}
    if(a==='batch-open')return batchOpen();if(a==='batch-keep'){capture();const p=state.page;p.keep.includes(id)?p.keep=p.keep.filter(x=>x!==id):p.keep.push(id);return render();}
    if(a==='batch-override'){capture();const p=state.page;push({type:'task',id,mode:'transfer',form:copy(p.overrides[id]||p.form),batchOverride:true});return;}
    if(a==='batch-preview')return batchPreview();
    if(a==='batch-submit'){const p=state.page,rows=p.ids.map(id=>({id,values:batchValues(id)}));const results=store.batch(rows,p.phase);const failed=results.filter(r=>!r.ok);results.filter(r=>r.ok).forEach(r=>state.selected.delete(r.id));closeLayer();if(!failed.length){store.draft(draftKey(),null);p.form=null;back();return toast('已逐人保存'+results.length+'项办理记录');}p.ids=failed.map(r=>r.id);render();return validation({ok:false,error:`${results.length-failed.length}人成功；${failed.map(r=>store.taskPerson(store.task(r.id)).name+'：'+r.error).join('；')}`});}
    if(a==='sample-photo')return samplePhoto();if(a==='clear-photos'){captureEvidence();(resolution||state.page.form).photos=[];return resolution?renderResolution():render();}if(a==='voice')return voiceOpen();
    if(a==='voice-example'){document.getElementById('departmentVoiceText').value=state.page.type==='execution'?'执行说明：已关闭作业区域，保留应急值守人员，现场情况已核实。':'投亲靠友，亲友姓名王晓梅，亲友关系子女，电话13700008890，地址洞头区北岙街道海滨路88号，老人已随身携带药品，等待亲友接应。';return;}
    if(a==='voice-record'){const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API)return toast('当前浏览器不支持语音转写，可输入文字或使用示例');speech=new API();speech.lang='zh-CN';speech.onresult=e=>{const text=[...e.results].map(r=>r[0].transcript).join('');const el=document.getElementById('departmentVoiceText');if(el)el.value=text;};speech.onerror=()=>toast('语音转写未完成，可重新输入');try{speech.start();}catch{toast('语音暂不可用，可输入文字');}return;}
    if(a==='voice-parse')return parseVoice();if(a==='voice-apply'){if(!voice?.preview)return;const preview=voice.preview,form=state.page.form;if(form.transferResult==='拒绝转移'){form.note=[form.note,document.getElementById('departmentVoiceText').value].filter(Boolean).join('；');closeLayer();return render();}const type=preview['destination.type'];if(type&&type!==form.destination?.type)form.destination={type};Object.entries(preview).forEach(([key,value])=>{if(key==='note')form.note=[form.note,value].filter(Boolean).join('；');else if(form.destination?.type==='center'&&key.startsWith('destination.')&&!['destination.type','destination.placeId','destination.detail','destination.careNeed'].includes(key))form.note=[form.note,value].filter(Boolean).join('；');else store.setPath(form,key,value);});closeLayer();return render();}
  },true);
  work.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='departmentSearchForm'){state.searchText=document.getElementById('departmentSearch').value;state.searchFocus=false;if(state.searchText.trim())store.remember(state.searchKind,state.searchText.trim());renderRecent();renderSearchRows();}});
  app.addEventListener('input',e=>{if(document.body.dataset.role!=='dept')return;const el=e.target;if(el.id==='departmentSearch'){state.searchText=el.value;renderRecent();renderSearchRows();}if(el.id==='departmentPickerSearch')renderPicker(el.value);if(el.id==='departmentMoveSearch'){renderDepartmentHTML(document.getElementById('departmentMoveRows'), store.units().filter(u=>u.name.includes(el.value)).map(u=>`<button class="dp-option" data-dp="move-confirm" data-id="${esc(u.id)}"><span>${esc(u.name)}</span><i data-tabler=chevron-right></i></button>`).join('')||empty('未找到已有单位'));}if(el.id==='departmentContactSearch'){const pos=el.selectionStart;state.query=el.value;contactsRender();const next=document.getElementById('departmentContactSearch');next.focus();next.setSelectionRange?.(pos,pos);}});
  app.addEventListener('focusin',e=>{if(e.target.id==='departmentSearch'){state.searchFocus=true;renderRecent();}});
  app.addEventListener('focus',e=>{if(e.target.id==='departmentSearch'){state.searchFocus=true;renderRecent();}},true);
  app.addEventListener('change',e=>{
    if(e.target.id!=='departmentPhoto'||document.body.dataset.role!=='dept')return;
    const file=e.target.files?.[0];if(!file)return;
    if(!file.type.startsWith('image/'))return toast('请选择图片文件');
    if(file.size>12*1024*1024)return toast('请选择12MB以内图片');
    captureEvidence();
    const account=store.account().accountId,page=state.page,correction=resolution,target=resolution||page.form;
    const reader=new FileReader();reader.onload=()=>{
      if(store.account().accountId!==account||(correction?resolution!==correction:state.page!==page))return;
      target.photos.push({id:'photo-'+Date.now(),src:reader.result,label:'现场照片'});
      if(correction)renderResolution();else render();
    };reader.readAsDataURL(file);
  });
  document.addEventListener('keydown',e=>{if(document.body.dataset.role==='dept'&&e.key==='Escape'&&!overlay.hidden)closeLayer();});
  window.DepartmentDemo={home,state,openUnit(uid){if(!store.unit(uid))return false;push({type:'unit',id:uid});return true;},openTask(tid){if(!store.task(tid))return false;taskOpen(tid);return true;},roleChanged(role){capture();closeLayer();state.selected.clear();state.batch=false;state.stack=[];state.page={type:'home'};if(role==='dept')render();}};
  context();
})();
